from research_helpers import *
a=ev('https://www.anjusoftware.com/press-release/general-press-release/anju-completes-merger-with-omnicomm-systems/','Completed 2019 acquisition identifies seven OmniComm eClinical offerings; does not attribute all Anju products to OmniComm.')
b=ev('https://www.anjusoftware.com/eclinical/','Current Anju clinical-research offering explicitly includes TrialMaster; other legacy products current availability unconfirmed.')
c=ev('https://www.anjusoftware.com/omnicomms-irtmaster-features/','IRTMaster functionality and historical OmniComm ownership confirmed.')
d=ev('https://www.anjusoftware.com/press-release/eclinical-press-release/edc-eclinical-press-release/fgk-clinical-research-signs-five-year-agreement-with-omnicomm-systems-for-multiple-eclinical-products/','Acuity Analytics is the named clinical-data visualization and risk-monitoring offering.')
products=[]
for name,desc,life,src,aliases in [('TrialMaster','Electronic clinical-trial data capture software.','commercial',b,[]),('TrialOne','Early-phase clinical research data and site software.','unknown',a,[]),('OmniComm eClinical Suite','Historical clinical-research software suite; bundle overlaps constituent applications.','unknown',a,['eClinical Suite']),('Promasys','Clinical research data management software.','unknown',a,[]),('IRTMaster','Clinical-trial randomization and investigational supply software.','unknown',c,[]),('OmniComm AutoEncoder','Clinical-research medical coding software.','unknown',a,['AutoEncoder']),('Acuity Analytics','Clinical-research data visualization and monitoring software.','unknown',d,['Acuity'])]:
 products.append(p(name,desc,src,life=life,typ='product',sub='research_tools',roles=['developer','owner'],aliases=aliases,evidence=[src,a] if src!=a else [a]))
co=dict(company_id='cmp_2b376739-526c-4355-a7ee-5d99ccd272f4',products=products,evidence=[a,b,c,d],status='partial',coverage_note='Seven named OmniComm clinical-research software offerings, including legacy suite bundle that overlaps applications. TrialMaster current commercial listing; historical products availability unknown. Anju completed acquisition September 2019; parent-only Luminee/TA Scan/CTMS Master not attributed to OmniComm without evidence. Partial: TrialOne Express and other historical named modules/offerings require further primary-source review.')
(out/'batch-0356.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
